registerRefData('nsw-cond-n-409',{"id":409,"pan":null,"ref":"24/1138","address":"2 Colo Street Mittagong 2575","description":"Alterations & Additions to Hotel","outcome":"approved","outcome_raw":"Approved","outcome_source":"planning_panels","determined":"2025-04-14","notice_url":"https://apps.planningportal.nsw.gov.au/prweb/PRRestService/DocMgmt/v1/PublicDocuments/DATA-WORKATTACH-FILE PEC-DPE-EP-WORK PPSSTH-405!20250414T071416.264 GMT","sha256":"8ba1b786a27d1f1bcb715f4a8eacc670f04faededa543836d2c7d17430f31119","pages":46,"layout":"numbered","n":13,"fetched_at":"2026-08-16T23:19:06+00:00","file":"n/409.js","source_page":"https://www.planningportal.nsw.gov.au/planning-panel/alterations-additions-hotel","lga":"WINGECARRIBEE","conditions":[{"label":"1","code":null,"number":"1","title":"PANEL REF - LGA - DA NO. PPSSTH-405 - WINGECARRIBEE - DA24/1138","text":"","stage":"general","stage_basis":"heading","page":5},{"label":"2","code":null,"number":"2","title":"","text":"PROPOSED DEVELOPMENT Alterations and refurbishment to existing Maltings 3 (M3) and construction\nof new Maltings 4 (M4) to create unified building for use as a hotel with\nrestaurant, exhibition and ancillary purposes","stage":"general","stage_basis":"heading","page":5},{"label":"3","code":null,"number":"3","title":"STREET ADDRESS 2 Colo Street, MITTAGONG (Lot 21 DP 1029384)","text":"","stage":"general","stage_basis":"heading","page":5},{"label":"4","code":null,"number":"4","title":"APPLICANT/OWNER Applicant: The Trustee for the Maltings Property Trust c/- Timothy Chung","text":"Owner: Halcyon Hotels Pty Ltd","stage":"general","stage_basis":"heading","page":5},{"label":"5","code":null,"number":"5","title":"TYPE OF REGIONAL","text":"DEVELOPMENT General development over $30 million","stage":"general","stage_basis":"heading","page":5},{"label":"6","code":null,"number":"6","title":"RELEVANT MANDATORY","text":"CONSIDERATIONS\n• Environmental planning instruments:\no State Environmental Planning Policy (Planning Systems) 2021;\no State Environmental Planning Policy (Resilience and Hazards)\n2021;\no State Environmental Planning Policy (Transport and\nInfrastructure) 2021;\no State Environmental Planning Policy (Biodiversity and\nConservation) 2021;\no State Environmental Planning Policy (Sustainable Buildings) 2022;\no Wingecarribee Local Environmental Plan 2010\n• Draft environmental planning instruments: Nil\n• Development control plans:\no Mittagong Township Development Control Plan 2010 (amended\n2021)\n• Planning agreements: Nil\n• Relevant provisions of the Environmental Planning and Assessment\nRegulation 2021\n• Coastal zone management plan: Nil\n• The likely impacts of the development, including environmental\nimpacts on the natural and built environment and social and economic\nimpacts in the locality\n• The suitability of the site for the development\n• Any submissions made in accordance with the Environmental Planning\nand Assessment Act 1979 or regulations\n• The public interest, including the principles of ecologically sustainable\ndevelopment","stage":"general","stage_basis":"heading","page":5},{"label":"7","code":null,"number":"7","title":"MATERIAL CONSIDERED BY","text":"THE PANEL\n• Council Assessment Report: 28 March 2025\n• Council Assessment memorandum- 9 April 2025\n• Letter to Wingecarribee Shire Council - The Maltings Draft Conditions\nof Consent - DA - 4 April 2025\n• Written submissions during public exhibition: 22\n• Verbal submissions at the public meeting:\no Mark Ghilardi\no Council assessment officer - Andre Vernez\no On behalf of the applicant - Simon Ip (Gyde), Mark Schofield\n(Gyde), Paul Davies (Heritage), Paul Lalich (K&L Gates), Kaare\nKrokene (Snohetta), Sarah Meyer (Snohetta), Lyndsey Beattie\n(Colliers), Phillipa Aiken (Colliers)\n• Total number of unique submissions received by way of objection: 20","stage":"general","stage_basis":"heading","page":5},{"label":"8","code":null,"number":"8","title":"MEETINGS, BRIEFINGS AND","text":"SITE INSPECTIONS BY THE\nPANEL\n• Briefing: 20 August 2024\no Panel members: Chris Wilson (Chair), Grant Christmas, Susan\nBudd, Richard Colley\no Council assessment staff: Andre Vernez\no Applicant representatives: Timothy Chung (Colliers), Phillipa Aiken\n(Colliers), Kaare Krokene, (Snohetta), Simon Ip (Gyde), Sarah\nMeyer (Snohetta), Paul Lalich (K&L Gates)\no D PHI : Amanda Moylan, Tracey Gillett\n• Site inspection: 20 August 2024\no Panel members: Chris Wilson (Chair), Grant Christmas, Susan\nBudd, Richard Colley\no C ouncil assessment staff: Andre Vernez\no Applicant representatives: Ben Bild\n• Final briefing to discuss council’s recommendation: 8 April 2025\no Panel members: Chris Wilson (Chair), Natasha Harras, Susan\nBudd, Richard Colley, Heather Warton\no C ouncil assessment staff: Andre Vernez, Jon Shillito, Parin Kolbadi\no DPHI: Amanda Moylan, Nikita Lange\no Applicant representatives: Simon Ip (Gyde), Mark Schofield\n(Gyde), Paul Davies (Heritage), Paul Lalich (K&L Gates), Kaare\nKrokene (Snohetta), Sarah Meyer (Snohetta), Lyndsey Beattie\n(Colliers), Phillipa Aiken (Colliers)","stage":"general","stage_basis":"heading","page":5},{"label":"9","code":null,"number":"9","title":"COUNCIL","text":"RECOMMENDATION Approval","stage":"general","stage_basis":"heading","page":6},{"label":"10","code":null,"number":"10","title":"DRAFT CONDITIONS Attached to the Council Assessment Report","text":"ADMINISTRATION CONDITIONS\n1. Development Description\nDevelopment consent has been granted in accordance with this notice of determination for\nthe purposes of alterations and refurbishment to the existing Maltings 3 (M3) and construction\nof a new Maltings 4 (M4) to create a unified building for use as a hotel with restaurant,\nexhibition and ancillary purposes.\nReason: To confirm the use of the approved development.\n2. Development in Accordance with Plans and Documents\nThe development shall be implemented in accordance with the approved plans and\nsupporting documents set out in the following table except where modified by any conditions\nof development consent.\nPlan Title / Supporting\nDocument\nReference /\nVersion\nPrepared By Dated\nStatement of\nEnvironmental Effects\n- Gyde Consulting 01/03/2024\n0100 - Overview\nPrecinct M3/4\nSite/Structure Plan\nReference No. 18-\n17 Sheet No. 0100\n(Revision E)\nSnohetta Australasia\nPty Ltd\n12/02/2023\n0300 - Demolition\nM3/4 Demolition Plan -\nBasement, Ground\n(L00)\nReference No. 18-\n17 Sheet No. M3/4\n300\n(Revision E)\nSnohetta Australasia\nPty Ltd\n12/02/2024\n0300 - Demolition\nM3/4 Demolition Plan -\nL01, L02\nReference No. 18-\n17 Sheet No. M3/4\n301\n(Revision E)\nSnohetta Australasia\nPty Ltd\n12/02/2024\n0300 - Demolition\nM3/4 Demolition Plan -\nL03, Roof\nReference No. 18-\n17 Sheet No. M3/4\n302\n(Revision E)\nSnohetta Australasia\nPty Ltd\n12/02/2024\n1100 - General\nArrangement - Floor\nPlans M3/4 Plan\nBasement\nReference No. 18-\n17 Sheet No. M3/4\n1100\n(Revision E)\nSnohetta Australasia\nPty Ltd\n12/02/2024\n1100 - General\nArrangement - Floor\nPlans M3/4 Plan L00 -\nL01\nReference No. 18-\n17 Sheet No. M3/4\n1101\n(Revision E)\nSnohetta Australasia\nPty Ltd\n12/02/2024\n1100 - General\nArrangement - Floor\nPlans M3/4 PLAN L02\nReference No. 18-\n17 Sheet No. M3/4\n1102\n(Revision E)\nSnohetta Australasia\nPty Ltd\n12/02/2024\nSCHEDULE 2 - AMENDED CONDITIONS OF CONSENT\n1100 - General\nArrangement - Floor\nPlans M3/4 Plan L03 -\nL04\nReference No. 18-\n17 Sheet No. M3/4\n1103\n(Revision E)\nSnohetta Australasia\nPty Ltd\n12/02/2024\n1100 - General\nArrangement - Floor\nPlans M3/4 Plan L05 -\nRoof\nReference No. 18-\n17 Sheet No. M3/4\n1104\n(Revision E)\nSnohetta Australasia\nPty Ltd\n12/02/2024\n2000 - Elevations\n(Exterior) M3/4\nElevations - North,\nEast, South, West\nReference No. 18-\n17 Sheet No. M3/4\n2000\n(Revision E)\nSnohetta Australasia\nPty Ltd\n12/02/2024\n3000 - Sections M3/4\nSections\nReference No. 18-\n17 Sheet No. M3/4\n3000\n(Revision E)\nSnohetta Australasia\nPty Ltd\n12/02/2024\n6000 - Schedules &\nDiagrams M3/4\nMaterials Schedule\nReference No. 18-\n17 Sheet No. M3/4\n6000\n(Revision E)\nSnohetta Australasia\nPty Ltd\n12/02/2024\nStormwater & Flood\nManagement Strategy\nReport\nReference No.\n110608-02\n(Issue D)\nJ. Wyndham Prince 24/10/2024\nHeritage Impact\nAssessment Report\n- Paul Davies Pty Ltd 02/2024\nFlora and Fauna\nAssessment Report\nReference No.\n23WOL7382\n(Version 5)\nEco Logical Australia\nPty Ltd\n27/02/2024\nVegetation\nManagement Plan\nReference No.\n14198\n(Version 6)\nEco Logical Australia\nPty Ltd\n20/02/2024\nDA Acoustic\nAssessment Report\nReference No.\n20230457.7\n(Revision 1)\nAcoustic Logic Pty Ltd 01/02/2024\nDA Structural Report Reference No.\n221582\n(Revision 2)\nTTW (NSW) Pty Ltd 06/02/2024\nDemolition and\nConstruction Waste\nManagement Plan\n- Waste Audit &\nConsultancy Services\n(Aust) Pty Ltd\n02/2024\nOperational Waste\nManagement Plan\n- Waste Audit &\nConsultancy Services\n(Aust) Pty Ltd\n02/2024\nReason: To ensure the development is carried out in accordance with the approved\nplans and documentation.\n2A. Modification of Consent for DA20/1400\nThis consent requires the modification of Development Consent 20/1400 approved on 13\nMay 2022 for concept development application No. 20/1400 that sets out a concept proposal\npursuant to section 4.22 of the Environmental Planning and Assessment Act 1979 for the\ndevelopment of the land known as 2 Colo Street Mittagong together with a detailed proposal\ncomprising Stage 1 of the application, as modified by 24/1140 on 13 March 2025.\nIt is a requirement of this condition that a new condition 11A is to be inserted into\nDevelopment Consent 20/1400 as follows:\nDespite any provision of this Development Consent 20/1400, this consent does not authorise\nor require anything that is inconsistent with the work approved in accordance with\nDevelopment Consent 24/1138 and to the extent of any inconsistency the latter consent\napplies. The terms of Development Consent 24/1138 must be satisfied when carrying out\ndevelopment under this consent.\nIt is a requirement of this condition that a new condition 11B is to be inserted into\nDevelopment Consent 20/1400 as follows:\nDespite condition 11, the development must be implemented in accordance with the following\napproved plans and documents:\nPlan Title / Supporting\nDocument\nReference /\nVersion\nPrepared By Dated\nStatement of\nEnvironmental Effects\n- Gyde Consulting 01/03/2024\n0100 - Overview\nPrecinct M3/4\nSite/Structure Plan\nReference No. 18-\n17 Sheet No. 0100\n(Revision E)\nSnohetta Australasia\nPty Ltd\n12/02/2023\n0300 - Demolition\nM3/4 Demolition Plan -\nBasement, Ground\n(L00)\nReference No. 18-\n17 Sheet No. M3/4\n300\n(Revision E)\nSnohetta Australasia\nPty Ltd\n12/02/2024\n0300 - Demolition\nM3/4 Demolition Plan -\nL01, L02\nReference No. 18-\n17 Sheet No. M3/4\n301\n(Revision E)\nSnohetta Australasia\nPty Ltd\n12/02/2024\n0300 - Demolition\nM3/4 Demolition Plan -\nL03, Roof\nReference No. 18-\n17 Sheet No. M3/4\n302\n(Revision E)\nSnohetta Australasia\nPty Ltd\n12/02/2024\n1100 - General\nArrangement - Floor\nPlans M3/4 Plan\nBasement\nReference No. 18-\n17 Sheet No. M3/4\n1100\n(Revision E)\nSnohetta Australasia\nPty Ltd\n12/02/2024\n1100 - General\nArrangement - Floor\nPlans M3/4 Plan L00 -\nL01\nReference No. 18-\n17 Sheet No. M3/4\n1101\n(Revision E)\nSnohetta Australasia\nPty Ltd\n12/02/2024\n1100 - General\nArrangement - Floor\nPlans M3/4 PLAN L02\nReference No. 18-\n17 Sheet No. M3/4\n1102\n(Revision E)\nSnohetta Australasia\nPty Ltd\n12/02/2024\n1100 - General\nArrangement - Floor\nPlans M3/4 Plan L03 -\nL04\nReference No. 18-\n17 Sheet No. M3/4\n1103\n(Revision E)\nSnohetta Australasia\nPty Ltd\n12/02/2024\n1100 - General\nArrangement - Floor\nPlans M3/4 Plan L05 -\nRoof\nReference No. 18-\n17 Sheet No. M3/4\n1104\n(Revision E)\nSnohetta Australasia\nPty Ltd\n12/02/2024\n2000 - Elevations\n(Exterior) M3/4\nElevations - North,\nEast, South, West\nReference No. 18-\n17 Sheet No. M3/4\n2000\n(Revision E)\nSnohetta Australasia\nPty Ltd\n12/02/2024\n3000 - Sections M3/4\nSections\nReference No. 18-\n17 Sheet No. M3/4\n3000\n(Revision E)\nSnohetta Australasia\nPty Ltd\n12/02/2024\n6000 - Schedules &\nDiagrams M3/4\nMaterials Schedule\nReference No. 18-\n17 Sheet No. M3/4\n6000\n(Revision E)\nSnohetta Australasia\nPty Ltd\n12/02/2024\nStormwater & Flood\nManagement Strategy\nReport\nReference No.\n110608-02\n(Issue D)\nJ. Wyndham Prince 24/10/2024\nHeritage Impact\nAssessment Report\n- Paul Davies Pty Ltd 02/2024\nFlora and Fauna\nAssessment Report\nReference No.\n23WOL7382\n(Version 5)\nEco Logical Australia\nPty Ltd\n27/02/2024\nVegetation\nManagement Plan\nReference No.\n14198\n(Version 6)\nEco Logical Australia\nPty Ltd\n20/02/2024\nDA Acoustic\nAssessment Report\nReference No.\n20230457.7\n(Revision 1)\nAcoustic Logic Pty Ltd 01/02/2024\nDA Structural Report Reference No.\n221582\n(Revision 2)\nTTW (NSW) Pty Ltd 06/02/2024\nDemolition and\nConstruction Waste\nManagement Plan\n- Waste Audit &\nConsultancy Services\n(Aust) Pty Ltd\n02/2024\nOperational Waste\nManagement Plan\n- Waste Audit &\nConsultancy Services\n(Aust) Pty Ltd\n02/2024\nThe modification is to be effected under section 4.17(1)(b) and section 4.17(5) of the\nEnvironmental Planning and Assessment Act 1979 prior to the issue of any construction\ncertificate for the subject building.\nThe required modifications:\n• are to be set out in a notice of modification of Development Consent 20/1400; and\n• must be lodged with the consent authority, in compliance with the requirements of section\n67 of the Environmental Planning and Assessment Regulation 2021 (“the EP&A\nRegulation”) in the terms prescribed by any condition of this consent that sets out a\nrequired modification to 20/1400.\n3. Inconsistency between documents\nIn the event of any inconsistency between the conditions of this consent and the\ndrawings/documents referred to above, the conditions of this consent shall prevail to the\nextent of the inconsistency.\nReason: To ensure that the development is undertaken in accordance with the\nsubmitted plans and documents (as amended).\n4. General Terms of Approval - Department of Planning and Environment-Water\nThe General Terms of Approval issued by the Department of Planning and Environment -\nWater, Reference No: IDAS -2024-10356, dated 4 July 2024 (as attached) are included as\nconditions of this consent and must be complied with.\nReason: To ensure ongoing compliance.\n5. General Terms of Approval - NSW Rural Fire Service\nThe General Terms of Approval issued by the NSW Rural Fire Service, Reference No:\nDA20240510001924-Original-1, dated 17 May 2024 (as attached) are included as conditions\nof this consent and must be complied with.\nReason: To ensure ongoing compliance.\n6. Concurrence - Water NSW\nThe Concurrence issued by Water NSW, Reference No: DAR 24047 -a1, dated 23 August\n2024 (as attached) are included as conditions of this consent and must be complied with.\nReason: To ensure ongoing compliance.\n7. Concurrence - Transport for NSW\nThe Concurrence issued by Transport for NSW, Reference No: STH24/00379/001, dated 24\nMay 2024 (as attached) are included as conditions of this consent and must be complied\nwith.\nReason: To ensure ongoing compliance.\n8. Erection of Signs\nA sign must be erected in a prominent position on any site on which building work, is being\ncarried out:\n(a) Showing the name, address and telephone number of the Principal Certifier (PC) for\nthe work, and\n(b) Showing the name of the principal contractor (if any) for any building work and a\ntelephone number on which that person may be contacted outside working hours, and\n(c) Stating that unauthorised entry to the work site is prohibited.\nAny such sign is to be maintained while the building work, subdivision work or demolition\nwork is being carried out, but must be removed when the work has been completed.\nReason: The condition is prescribed under clause 98A of the Environmental Planning\nand Assessment Regulation 2000.\n9. Compliance with Disability Discrimination Act 1992\nThis approval does not protect or guarantee against a possible claim of discrimination\n(intentional or unintentional) under the Disability Discrimination Act 1992 , and the\napplicant/owner is therefore advised to investigate their liability under this Act.\nReason: To inform of relevant access requirements for persons with a disability.\nNote: Disability (Access to Premises - Buildings) Standards 2010 -As of 1 May 2011,\nif access is provided to the extent covered by this Standard, then such access\ncannot be viewed as unlawful under the Disability Discrimination Act 1992.\n10. Demolition Requirements\nDemolition work shall be carried out in accordance with the requirements of AS2601- 2001\n\"The Demolition of Structures\".\nAmongst others, precautions to be taken shall include compliance with the requirements of\nthe SafeWork NSW and Council’s Water and Sewer Asset Protection, including:-\n(a) Protection of site workers and the general public.\n(b) Erection of hoardings where appropriate.\n(c) Asbestos removal handling and disposal where applicable by licensed contractors.\n(d) Ensuring only licensed demolition contractors are used as required pursuant to\nOccupational Health and Safety Legislation.\n(e) Appropriate precautions are taken in regard to lead based paints.\nReason: To comply with statutory requirements.\n11. Fire Safety Existing Building Upgrade\nPursuant to Section 64 of the Environmental Planning and Assessment Regulation 2021, the\nentire existing building is to be upgraded in the following manner to bring the building into\ncompliance with the BCA:\n(a) The development is to be upgraded to comply with Sections C,D,E & F of the NCC\n2022 Volume One - Building Code of Australia.\nBefore the issue of an Occupation Certificate, information must be prepared by a suitably\nqualified person and demonstrate, to the principal certifier’s satisfaction, that the\ndevelopment will comply with the required building upgrades.\nReason: To protect occupants in the event of an emergency and to ensure that the\ndevelopment is serviced by adequate fire safety measures.\n12. ARTC - Stormwater\nThe developer is to ensure that stormwater does not affect the rail corridor.\nReason: To ensure no impact to the adjoining rail corridor.\n13. Sewer Main Augmentation\nSewer main augmentations must be carried out in accordance with the Water and Sewer\nModelling report prepared by Urban Water Solutions, dated 22 April 2020.\n14. Remediation\nThe site shall be remediated in accordance with:\na) Remedial Action specified in the Interim Audit Advice or Section B5 Site Audit\nStatement t issued by a NSW EPA Accredited Auditor for Contaminated Land;\nb) State Environmental Planning Policy (Resilience and Hazards) 2021;\nc) National Environment Protection (Assessment of Site Contamination) Measure (ASC\nNEPM), 1999 as amended in 2013); and\nd) applicable NSW EPA contaminated land guidelines.\nReason: Compliance and statutory requirements.\n15. Compliance with Environmental Management Plan\nThe applicant shall comply with any Environmental Management Plan (EMP) referred to in\nSection A2 of the Site Audit Statement during the construction and operation of the\ndevelopment.\nReason: Compliance and statutory requirements.\nCONDITIONS TO BE SATISFIED PRIOR TO THE COMMENCEMENT OF WORK\n16. Notice of Commencement\nNo work shall commence until a notice of commencement form has been submitted (form will\nbe attached with issue of a Construction Certificate or Subdivision Works Certificate or\navailable from Council’s website), giving the Principal Certifier (PC):\n(a) Not less than two (2) days’ notice of the date on which it is proposed to commence\nwork associated with this Development Consent;\n(b) Details of the appointment of a Principal Certifier (PC) (either Wingecarribee Council\nor another Accredited Certifier)\n(c) Details of the Principal Contractor or Owner Builder.\n Name\n Builders Licence Number or Owner Builder Permit Number\n Principal Contractor Company Name\n Principal Contractor ABN\n Address of Principal Contractor or Owner Builder\n Email Address\n(d) Copy of the HBCF Insurance Certificate (if residential building works exceed $20,000)\nor Owner Builder Permit;\n(e) Details demonstrating compliance with development consent conditions relevant prior\nto commencement of the development been satisfied.\nReason: Statutory requirement.\n17. Fencing of the Construction Site\nA temporary hoarding or temporary construction site fence must be erected between the work\nsite and adjoining lands before the works begin and must be kept in place until after the\ncompletion of the works if the works:\n(a) could cause a danger, obstruction or inconvenience to pedestrian or vehicular traffic,\nor\n(b) could cause damage to adjoining lands by falling objects, or\n(c) involve the enclosure of a public place or part of a public place.\nReason: To ensure that the safety of the public is not compromised.\n18. Utility Services\nIf the work requires alteration to, or the relocation of, utility services on, or adjacent to, the lot\non which the work is carried out, the work is not complete until all such works are carried out.\nReason: To ensure that utilities are provided appropriately to the development.\n19. Erosion and Sediment Control\nErosion and sediment control measures (as per the approved Erosion and Sediment Control\nPlan) shall be installed prior to the commencement of works.\nReason: To ensure that sediment does not leave the site as a result of the construction\nof the development.\n20. Habitat Bearing Tree Survey\nA Habitat Bearing Tree survey must be undertaken prior to construction commencing. The\necologist must inspect all trees (native and exotic) proposed for removal, aiming to identify\nhollows, nests, dreys or other fauna habitat. Of note, the Pines contain possum dreys and\nhollows which must be suitably managed to ensure harm to fauna is minimised as much as\npossible. Where habitat is being removed, a commensurate habitat replacement must be\nintroduced with a preference for hollows drilled into retained trees rather than only nest boxes\nbased on advice from the project ecologist. Compensatory hollows or nest boxes should be\nsimilar in size and dimension to hollows being removed.\n21. Heritage site induction (‘toolbox talks’)\nPrior to the commencement of any works, all contractors, tradesmen and the like, shall be\ngiven a heritage site induction (‘toolbox talk’).\nThe heritage site induction shall be delivered by a suitably qualified Heritage Consultant and\nshall ensure that all contractors, tradesmen and the like, are made aware that:\ni) The site contains an item of heritage significance.\nii) All conservation works to the heritage item are to be undertaken in accordance with the\nSchedule of Conservation Works and undertaken by suitably qualified tradesmen.\niii) There are statutory obligations under the National Parks and Wildlife Act 1974 and\nHeritage Act 1977 for all works to cease and Heritage NSW notified of any unexpected built\narchaeological or Aboriginal archaeological finds during works.\nReason: To ensure all persons undertaking works on the site are aware of the heritage\nrestrictions and obligations.\n22. Photographic Archival Recording\nPrior to the commencement of any works, including the dismantling of fabric or demolition, a\nPhotographic Archival Recording shall be undertaken of all buildings and structures on the\nsite, including their interiors, exteriors and surrounding landscape and submitted to Council.\nWritten confirmation must also be obtained from Council’s Heritage Advisor, confirming that\nthe Photographic Archival Recording is of an acceptable quality that satisfies the\nrequirements of this condition.\nThe Photographic Archival Recording shall be prepared in accordance with the guidelines\n\"Archival Recording of Heritage Items Using Film or Digital Capture\" published by the\nHeritage Council of NSW.\nOne complete copy of the Photographic Archival Recording shall be submitted to Council\nand should contain (for digital projects):\n• A brief report or introduction which explains the purposes of the Photographic Archival\nRecording and gives a brief description of the subject site, as well as details of the sequence\nin which images were taken. The report may also address the limitations of the photographic\nrecord and may make recommendations for future work;\n• Measured plans of the building at 1: 100 scale;\n• A site plan of the building at min 1: 200 scale;\n• Plans of the building marked up to indicate where the photographs were taken and the\ndirection of the photograph;\n• The report should include all technical details including camera and lenses, image file size\nand format, technical metadata associated with the images, and colour information;\n• Catalogue sheets, photographic plan, supplementary maps;\n• Colour thumbnail image sheets (e.g. A4 page with six images by six images) showing\nimages and reference numbers. The thumbnail sheets should be processed with archivally\nstable inks on archivally acceptable photographic paper and cross referenced to catalogue\nsheets;\n• One full set of 10.5x14.8cm (A6) colour prints OR, if a large project, a representative set of\nselected images processed with archivally stable inks on archivally acceptable photographic\npaper.\n• A CD or DVD containing electronic image files saved as RAW and JPEG files with\nassociated metadata, and cross-referenced to catalogue sheets.\nThe report should be presented on archival quality paper in a suitable archival binder and\nslipcase, and all storage of individual components must be in archival quality packaging\nsuitable for long term storage.\nReason: Heritage conservation.\n23. Aboriginal heritage\n(a) Aboriginal Cultural Heritage Assessment\nAn Aboriginal cultural heritage assessment report (ACHAR) must be prepared for the site,\nadhering to OEH April 2011 (see below) and submitted to and approved by Council prior to\nthe issue of a Construction Certificate and prior to the commencement of any work (including\nany demolition or excavation work) on -site. The ACHAR must investigate and assess the\nfour separate aspects of Aboriginal cultural heritage outlined under OEH April 2011-not just\nthe potential for Aboriginal objects.\n(b) Aboriginal Community Consultation\nFormal Aboriginal community consultation is to be conducted in accordance with Heritage\nNSW guidelines and the National Parks and Wildlife Regulation 2019. This is undertaken as\npart of the ACHAR, in line with DECCW April 2010.\nAboriginal community consultation must commence before any archaeological test\nexcavation and must be completed prior to the issue of any Construction can occur Certificate\nand prior to the commencement of any demolition or excavation work onsite.\n(c) Aboriginal Test Excavation\nThe Aboriginal heritage assessment has identified four areas where archaeological test\nexcavation is recommended (KAS 2020, pp.56- 57). Test excavation must be and must be\ncompleted prior to the issue of any undertaken at an early stage Construction Certificate and\nprior to the commencement of any demolition or excavation work onsite to provide the best\nopportunity to prevent harm to Aboriginal cultural heritage and avoid delays during the\nconstruction process. Archaeological test excavation can occur as par t of the ACHAR and\nadhere with the Code of Practice (DECCW 24 September 2010) without need for an AHIP.\nWith respect to all other works, no harm may occur to Aboriginal objects unless an AHIP has\nbeen issued, or the process of Aboriginal test excavation has proven no Aboriginal objects\nare present and the ACHAR has been prepared to provide a due diligence defence against\nharm (DECCW 13 September 2010).\nNo ground disturbance, including for geotechnical investigations, may be conducted in areas\nof Potential Archaeological Deposit and archaeological sensitivity (KAS 2020, p.47) unless\nan Aboriginal Heritage Impact Permit (AHIP) has been issued by Heritage N SW or the due\ndiligence defence is in place.\n• DECCW Aboriginal cultural heritage consultation requirements for proponents 2010. Part 6\nNational Parks and Wildlife Act 1974 (April 2010);\n• DECCW Due Diligence Code of Practice for the Protection of Aboriginal Objects in NSW\n(13 September 2010);\n• DECCW Code of Practice for Archaeological Investigation of Aboriginal Objects in New\nSouth Wales (24 September 2010);\n• OEH Guide to investigating, assessing and reporting on Aboriginal cultural heritage in NSW\n(April 2011);\n(d) AHIP application\nShall the site contain Aboriginal objects, and these will be impacted by the proposed\ndevelopment, an AHIP will be required from Heritage NSW prior to any works commencing\non site.\nReason:","stage":"general","stage_basis":"heading","page":6},{"label":"1","code":null,"number":"1","title":"","text":"The LEP listing notes that the site includes remnants of earlier enterprises on the site that\npre-date the Maltings.","stage":"general","stage_basis":"heading","page":16},{"label":"2","code":null,"number":"2","title":"Landscape and other aspects of the Maltings may hold heritage and archaeological","text":"significance.","stage":"general","stage_basis":"heading","page":16},{"label":"3","code":null,"number":"3","title":"","text":"All historical archaeological ‘relics’ with heritage value are protected by s139- 140 of the\nNSW Heritage Act, 1977, and any requirements for archaeological excavation permits shall\nbe known before works on site can commence.\nCONDITIONS TO BE SATISFIED PRIOR TO THE ISSUE OF THE CONSTRUCTION\nCERTIFICATE\n24. Application for a Construction Certificate (Building Works)\nThe applicant shall apply to Council or a Registered Certifier for a Construction Certificate to\ncarry out the relevant building works in accordance with this consent. The details to be\nincluded in the application for a Construction Certificate are:\n(a) Architectural plans and building specifications complying with the National\nConstruction Code (NCC) relevant Australian Standards, and the development\nconsent and conditions.\n(b) If Council or a private Registered Certifier issues the Construction Certificate,\nengineering details must be submitted for approval for all structural elements.\n(c) Essential services plan outlining the existing and proposed fire safety measures.\n(d) Structural Engineers Design Certificate for all structural elements, indicating\ncompliance with Part B of volume one of the National Construction Code and relevant\nAustralian Standards.\n(e) If a performance solution is proposed, the following details must be lodged:\n(i) Performance Based Design Brief;\n(ii) Performance requirements that the performance solution intends to meet.\n(iii) Assessment methods used to determine compliance with the performance\nrequirements, including if and how each performance objective impacts on\nother requirements of the NCC;\n(iv) Final report - demonstrate compliance with the NCC Performance\nRequirements agreed in the PBDB; and\n(v) A statement about the person who prepared the performance solution,\nindicating qualifications, experience, insurance details, and membership of an\napproved accreditation body.\nReason: A requirement under the provisions of the Environmental Planning and\nAssessment Act 1979.\n25. Long Service Levy Payments\nThe payment of a long service levy as required under Part 5 of the Building and Construction\nIndustry Long Service Payments Act 1986, in respect to this building work, and in this regard,\nproof that the levy has been paid, is to be submitted to Council prior to the issue of a\nConstruction Certificate.\nCouncil acts as an agent for the Long Services Payment Corporation and the levy may be\npaid at Council’s Office.\nReason: Statutory requirement\n26. Water Management Act - Certificate of Compliance\nA Certificate of Compliance under Division 5 of Part 2 of Chapter 6 of the Water Management\nAct 2000 shall be obtained prior to the issue of the Construction Certificate.\nNote: Section 64 of the Local Government Act 1993 authorises Council to issue Certificates\nof Compliance under Section 306 of the Water Management Act 2000. Section 64 of\nthe Local Government Act 1993 also authorises Council to impose pre- conditions to\nthe issuing of Certificates of Compliance.\nAs a precondition to the issuing of a Certificate of Compliance, Council requires the payment\nof Developer Charges prior to the issue of the relevant Construction Certificate as prescribed\nby Council’s Development Servicing Plans.\nA Developer Charges - Notice of Payment is attached to the back of this consent and outlines\nmonetary contributions and unit rates applicable at the time of issue of this consent.\nThe water, sewer and stormwater headworks levies are indexed quarterly in accordance with\nupward movements in the Consumer Price Index (All Groups, Sydney) as published by the\nAustralian Bureau of Statistics (www.abs.gov.au <http://www.abs.gov.au>) and Council’s\nDevelopment Servicing Plans.\nCopies of Development Servicing Plans are available at Wingecarribee Shire Council’s\nAdministration building Moss Vale or are available for download from Council’s website\nwww.wsc.nsw.gov.au <http://www.wsc.nsw.gov.au>.\nThe Water and Sewerage Development Servicing Plans (DSP’s) adopted by Council came\ninto effect on 15 September 2017. The Stormwater DSP was adopted on 9 November 2010\nand came into effect on 8 December 2010. The current charges under these Plans are listed\nas follows:\nCPI Period Water DSP Sewer DSP Stormwater DSP\nTo 30th April 2025 $13,371.28 $12,962.98 $-\nNote: The charges shown above are amounts applicable during the stated time period.\nThese amounts will be subject to adjustment quarterly in accordance with upward\nmovements in the Consumer Price Index ( CPI) once they become operational. The\nCPI is published quarterly by the Australian Bureau of Statistics, www.abs.gov.au\n<http://www.abs.gov.au>.\nShould new DSP’s be prepared, it is possible that the charges may increase significantly.\nDraft DSP’s must be advertised by Council for a period of 30 days prior to adoption.\nNote: Payment of the above charges is to be by BANK CHEQUE OR CASH and is to be\naccompanied by the attached sheet entitled \"Notice of Payment - Developer Charges\n& Section 94\". Should the Applicant pay by personal or company cheque, the plans\nsubject to this approval will not be available for collection until such time as the cheque\nhas been honoured (i.e., a minimum of 10 days).\nCompliance Certificate\nCompliance Certificate fees, in accordance with Council’s Revenue Policy, are as follows and\nshall be paid prior to the issue of the relevant Construction Certificate:\nWater $273 + Sewer $273 + Stormwater $- = $546\nPrior to final release, you will need to contact Council’s Infrastructure Services Division for\nan inspection to ensure that Council will accept the infrastructure constructed. In response,\nthe Manager of Water and Sewer will specify requirements which will have to be met.\nIn the case of subdivision, the title plan of subdivision will not be certified and released by\nCouncil until the Water Management Act 2000 charges have been paid and/or secured and\nthe approval of Council has been obtained for all works related to this infrastructure.\nIn the case of other forms of development, the Construction Certificate will not be issued until\nthe Water Management Act 2000 charges have been paid and/or secured and the approval\nof Council has been obtained.\nReason: To retain a level of service for the existing population and to provide the same\nlevel of service to the population resulting from new developments.\n27. Asbestos Management Plan (AMP)\nThe applicant shall engage the services of a suitably qualified contaminated land consultant\nto prepare an AMP in accordance with section 429 of the Work Health and Safety Regulation\n2017 to address the risks associated with friable and bonded asbestos encountered at the\nsite. As part of the AMP , a SafeWork NSW Class A licensed contractor must be engaged to\ncarry out an 'emu pick' to remove all visible ACM from the site surface. An interim\nmanagement strategy for the stockpiles is to be outlined within the AMP.\nA surface clearance certificate issued by a SafeWork NSW Licensed Asbestos Assessor shall\nbe obtained and submitted to the satisfaction of Council’s Environmental Health Officer prior\nto the issue of any Construction Certificate.\nReason: Compliance and statutory requirements.\n28. Remedial Action Plan (RAP)\nThe applicant shall engage the services of a suitably qualified contaminated land consultant\nto prepare a site Remedial Action Plan (RAP) in compliance with the NSW EPA statutory\nguidelines Consultants Reporting on Contaminated Land: Contaminated Land Guidelines\nand to the satisfaction of a NSW EPA Accredited Auditor for Contaminated Land.\nThe RAP shall be provided to Council’s Environmental Health Officer prior to the\ncommencement of any remediation works and prior to the issue of any Construction\nCertificate.\nReason: Compliance and statutory requirements.\n29. Section B5 Site Audit Statement or Interim Audit Advice\nPrior to the commencement of any remediation works the applicant shall engage the services\nof a NSW EPA Accredited Auditor for Contaminated Land to audit the RAP and issue an\nInterim Audit Advice or Section B5 Site Audit Statement in a form approved under the NSW\nSite Auditor Scheme. The Interim Audit Advice or Section B5 Site Audit Sta tement shall\ncontain a clear declaration by the Auditor that the site can be made suitable for the intended\nuse if the site is remediated in accordance with the RAP.\nThe Interim Audit Advice or Section B5 Site Audit Statement shall be submitted to Council’s\nEnvironmental Health Officer prior to the commencement of any remediation works and prior\nto the issue of any Construction Certificate.\nReason: Compliance and statutory requirements.\n30. Validation Report\nThe applicant shall engage the services of a suitably qualified contaminated land consultant\nto prepare a site Validation Report in compliance with the NSW EPA statutory guidelines\nConsultants Reporting on Contaminated Land: Contaminated Land Guidelines and to the\nsatisfaction of a NSW EPA Accredited Auditor for Contaminated Land.\nThe Validation Report shall be submitted to Council’s Environmental Health Officer prior to\nthe issue of any Construction Certificate.\nReason: Compliance and statutory requirements.\n31. Site Audit Report and Site Audit Statement\nThe applicant shall engage the services of a NSW EPA Accredited Auditor for Contaminated\nLand to prepare a Site Audit Report and Site Audit Statement Section A1 or Section A2\n(whichever is applicable) in a form approved under the NSW Site Auditor Scheme. The Site\nAudit Statement Section A1 or Section A2 shall contain a clear declaration by the Auditor that\nthe site is suitable for the intended use.\nThe Site Audit Report and Site Audit Statement Section A1 or Section A2 (whichever is\napplicable) shall be submitted to Council’s Environmental Health Officer prior to the issue of\nany Construction Certificate.\nReason: Compliance and statutory requirements.\n32. Appointment of Principal Certifier (PC)\nNo work shall commence in connection with this Development Consent until:\n(a) A Construction certificate for the building work has been issued by:\n(i) the consent authority; or\n(ii) an accredited certifier; and\n(b) the person having the benefit of the development consent has:\n(i) appointed a Principal Certifier (PC) for the building work, and\n(ii) notified the Principal Certifier (PC) that the person will carry out the building\nwork as an owner-builder, if that is the case, and\n(b1) the Principal Certifier (PC) has, no later than 2 days before the building work\ncommences:\n(i) notified the Council of his or her appointment, and\n(ii) notified the person having the benefit of the development consent of any\ncritical stage inspections and other inspections that are to be carried out in\nrespect of the building work, and\n(b2) the person having the benefit of the development consent, if not carrying out the work\nas an owner builder, has:\n(i) appointed a principal contractor for the building work who must be the holder\nof a contractor licence if any residential building work is involved, and\n(ii) notified the Principal Certifier (PC) of such appointment, and\n(iii) unless that person is the principal contractor, notified the principal contractor\nof any critical stage inspections and other inspections that are to be carried\nout in respect of the building work, and\n(c) the person having the person having the benefit of the development consent has\ngiven at least 2 days’ notice to the Council of the person's intention to commence the\nerection of the building.\nReason: To ensure that there is certainty as to the consent applying to the land.\n33. Developer to provide photos of damage to Council property\nThe developer must provide Council and the Principal Certifier (PC) with photos of any\ndamage of Council property adjoining the development prior to the issue of the Construction\nCertificate.\nPhotos should include any damage to footpaths, road furniture, landscaping/trees, drainage,\nwater, sewer, kerb and gutter and road pavement and the like.\nFailure to identify existing damage will result in all damage detected after completion of the\nbuilding work being repaired at the developer/owners/proponents expense.\nThe construction supervisor is responsible to ensure that all contractors, sub-contractors, and\ndelivery trucks use a designated access point to prevent damage to Council's property.\nRepairs to damaged Council property are to be carried out by the contract or/builder to\nCouncil's specification and supervision prior to issue of any Occupation Certificate.\nReason: To ensure that Councils assets are protected.\n34. Access for People with Disabilities\nAccess for people with disabilities shall be provided in accordance with the requirements of\nthe National Construction Code, relevant Australian Standards and with regard to the\nDisability Discrimination Act 1992.\nPrior to the issue of a Construction Certificate, the plans shall demonstrate compliance.\nNote: Disability (Access to Premises - Buildings) Standards 2010 - As of 1 May\n2011, if access is provided to the extent covered by this Standard, then such\naccess cannot be viewed as unlawful under the Disability Discrimination Act\n1992.\nReason: To inform of relevant access requirements for persons with a disability.\n35. Section 68 Local Government Act 1993 Approvals\nPrior to the issue of a Construction Certificate, an application under section 68 of the Local\nGovernment Act 1993 shall be made to, and issued by, Wingecarribee Shire Council, for the\nfollowing approvals:\n• Carry out sewerage works\n• Carry out water supply\n• Carry out stormwater construction works\nReason: A requirement under the provisions of the Local Government Act 1993.\n36. Water and Sewer Authority Conditions\nPrior to issue of a Construction Works Certificate, the developer shall obtain approval from\nCouncil (as the Water Supply Authority and/or as required under Section 68 of the Local\nGovernment Act 1993) for the works to be undertaken by submitting adequate documentation\nincluding plans, calculations and specifications which justify that the required works are in\naccordance with all Council’s standards and all other relevant codes and guidelines.\nReason: To ensure water and sewer reticulation are in accordance with Council’s\nstandards.\n37. Building within Vicinity of Sewer Main\nWhere any civil works and machine tracking are undertaken within the zone of influence of\nthe sewer main, detailed plans must be provided prior to the issue of the Section 68 approval.\nReason: To protect public infrastructure.\n38. Network Connection - Endeavour Energy\nPrior to the issue of a Construction Certificate, an appropriate application will need to be\nsubmitted to Endeavour Energy based on the maximum demand for electricity for connection\nof load.\nReason: To ensure appropriate infrastructure is provided to the development.\n39. Section 138 Roads Act 1993 Approval\nWhere works are proposed within the road reserve, the developer must obtain approval from\nCouncil (as the Roads Authority and/or as required under Section 138 of the Roads Act 1993)\nbefore any works are undertaken. Works within the road reserve may include activities such\nas erect a structure, dig up or disturb the surface of a public road, remove or interfere with a\nstructure, or any other activities as defined within the Roads Act 1993.\nThe following details must be submitted to Council in order to obtain the Section 138\napproval:\n• A copy of approved design plans related to the development and proposed works to be\nundertaken.\n• Traffic Control Plan (TCP) to provide protection for those within and adjacent to the\nwork site, including the travelling and pedestrian public. The TCP must comply with the\nRoads and Traffic Authority’s manual ‘”Traffic Control at Work Sites”. Warning and\nprotective devices shall comply with the provisions of AS1742.3 - 2002 Traffic Control\nDevices for Works on Roads. The plan must be prepared and certified by a person\nholding the appropriate Roads and Traffic Authority accreditation, a copy of which is to\nbe submitted with the plan.\n• Insurance details - Public Liability Insurance to an amount of $20 million, to be held by\napplicant / contractor undertaking the works.\nAdvice: Where works are required within a Classified Road, the Developer must obtain\nthe concurrence and / or the approval of the Roads and Maritime Services for\nengineering design plans, Traffic Control Plans and approvals under Section\n138 of the Roads Act 1993.\nReason: Statutory requirement.\n40. Dilapidation Report\nA Dilapidation Report shall be undertaken on all properties, which in the opinion of a suitably\nexperienced professional and chartered qualified engineer, could be potentially affected by\nthe construction of the project. The Dilapidation Report shall be carried out taking into account\ncivil infrastructure and submitted to Council prior to the issue of the Construction Certificate.\nThe Report shall cover structural and geotechnical factors likely to arise from the\ndevelopment.\nThe person having the benefit of the development consent shall, at their own cost, rectify any\ndamage caused to other properties during the construction of the project to the satisfaction\nof Council.\nReason: To ensure the structural stability of neighbouring buildings.\n41. Structural Engineer’s Details\nStructural engineering plans are to be prepared by an experienced professional chartered\npracticing Structural Engineer for the following work shall be lodged with the Principal\nCertifying Authority and approved prior to commencing the works in accordance with a\nConstruction Certificate:\nAdvice: The name, address and qualifications of the practising Structural Engineer\ncertifying the design shall be clearly indicated on the plans and any\naccompanying documentation. Such engineer is to hold qualifications\nappropriate to the project as defined in the Building Code of Australia. The\ndesign shall relate to the particular site.\nAdvice: Any such Certificate is to set forth the extent to which the Engineer has relied\non relevant Specifications, Rules, Codes of Practice or Publications in respect\nof the construction.\nReason: To ensure the structural integrity of the building is achieved.\n42. Construction Management Plan\nTo undertake development works including demolition, earthworks and construction a\nConstruction Management Plan (CMP) is required to be submitted and approved by Council\nprior to issue of the Construction Certificate. The CMP shall indicate measures to be\nimplemented to mitigate construction risks in the protection of the environment as well as\npublic health, safety and convenience. The CMP must address the following:\na) Details of site security;\nb) Off-street parking for employees, contractors and sub-contractors.\nc) Public safety in the use of roads and footpaths where development activities interacts\nwith existing facilities and operations.\nd) The storage and removal, on a regular frequency, of builder’s rubble and waste by\ntrade waste contractors.\ne) Provision for loading and unloading materials;\nf) Location of all building materials, structures, plant and equipment to be stored or\nplaced within the construction site;\ng) How materials are to be loaded/unloaded and potential impact on Council\ninfrastructure (including but not limited to footpaths and street trees)\nh) Public risk policies and management for all contractors’ employees using or gaining\naccess over public footpaths and roads.\ni) External lighting and security alarms proposed for the construction site.\nj) Firefighting measures to be available on site during development and construction.\nk) Sanitary amenities proposed on site during development and construction.\nl) Ensuring the safety of members of the public and Council staff who may have\noccasion to enter and be in attendance on the site;\nm) Details of management of storm water run-off and the propose sediment and erosion\ncontrol measures including the location of any rubble grids;\nn) Details of any air and dust management;\no) Details of noise and vibration controls;\np) Anticipated staging and duration of works\nq) Provision of Construction Traffic Management Plan (CTMP) and Traffic Control Plans\n(TCP) addressing construction related traffic issues including:\n• Surrounding traffic environment including roads, public transport and existing\nparking restrictions\n• Truck routes to and from the site\n• General site access and egress for construction vehicles and equipment\npurposes\n• Frequency of truck movements\n• Sweep paths for trucks entering, circulating and exiting site\n• Location of vehicle standing areas to load and unload and any work zones (if\nrequired)\n• Impact of works on residents, businesses, pedestrians, cyclists, local traffic,\nemergency services and management of staff parking\n• Directional signage for pedestrian and trafficable areas\nReason: To ensure the safety, amenity and protection of public infrastructure and the\nenvironment.\n43. Stormwater - Control of Peak Discharge\nAdequate and suitable infrastructure shall be provided to ensure the peak discharge from the\nsite is no greater than the pre- developed peak discharge. This infrastructure shall be\ndesigned in accordance with Council’s Engineering Design Construction Specifications and\nDrawings. Calculations to demonstrate that the post -development peak discharge w ill not\nexceed the pre- development peak discharge shall be provided with the application for a\nConstruction Certificate.\nAny stormwater temporarily stored onsite shall be done in a manner that does not jeopardise\npublic safety. In this regard the development shall provide a risk assessment with the\nConstruction Certificate documentation.\nReason: To ensure the peak discharge from the site is no greater than the pre-\ndeveloped peak discharge.\n44. Detailed Stormwater Drainage System Design\nPrior to the issue of the Construction Certificate, a detailed storm water hydraulic drainage\nplan for the disposal of storm water from the site, prepared in accordance with Council’s\nDesign Standards shall be submitted to Council and approved by Council’s Development\nEngineer.\nShould any changes be required to the approved storm water drainage plan, the amended\ndesign shall achieve equivalent performance standards in accordance with Design\nSpecifications.\nNote: Construction Certificate Approval does not include approval for works external\nto the property or civil works.\nWhere the proposed design extends beyond the property boundary, separate approval under\nSection 138 of the Roads Act 1993, must be obtained from Council prior to the\ncommencement of works.\nThe applicant is advised to contact Council for clarification of proposed works for which\napproval under Section 138 of the Roads Act 1993 applies.\nReason: To ensure adequate storm water management.\n45. Carpark Design - Site Servicing\nThe car park shall be designed to accommodate the turning movements of the largest vehicle\nservicing the development. The car park design shall incorporate the following:\na) The site shall accommodate the turning movements of applicable service vehicles.\nb) Service vehicles shall manoeuvre into and out of the site in a forward direction.\nc) The front overhang, and swept path made by the service vehicle shall not obstruct car\npark traffic or encroach onto parking spaces.\nd) The vehicle swept path shall be reflected on the engineering design plans.\ne) Loading and unloading of service vehicles shall be undertaken onsite with no intrusion\nonto the road system.\nf) The footpath crossing shall be splayed from the property boundary to the kerb line to\naccommodate the swept path made by the service vehicle.\nReason: To ensure that the car parking area is constructed to Council requirements.\n46. Accessible Car Parking Spaces\nOne (1) of the car parking spaces provided as part of the total requirement shall be reserved\nfor disabled persons.\nThese spaces shall be constructed and identified in accordance with Volume 1 of the National\nConstruction Code (NCC) and AS/NZS 2890.6 - Parking Facilities, Off -street parking for\npeople with disabilities.\nDetails to demonstrate compliance shall be submitted to and approved by the Certifying\nAuthority prior to the issue of the Construction Certificate.\nReason: To inform of relevant access requirements for persons with a disability.\n47. Off Street Parking Provision - Basement Parking\nFour (4) basement car parking spaces suitably marked in accordance with the approved\nplans (unless elsewhere specified) shall be provided. Each space shall have minimum\ndimensions in accordance with Australian Standard AS2890.1 Off Streetcar Parking.\nDetails shall be submitted to the Accredited Certifier prior to the issue of a Construction\nCertificate showing compliance with this condition.\nReason: To ensure adequate parking and access.\n48. Erosion and Sediment Control Plan\nAn Erosion and Sediment Control Plan shall be prepared in accordance with “Landcom’s\nBlue Book” for sedimentation and erosion control plan by a suitably qualified person, and\napproved by Council prior to issue of the Construction Certificate.\nThe Erosion and Sediment Control Plan shall include scaled drawings and detailed\nspecifications which can be referred to onsite by project management staff or project\nconstruction supervisor. Items to be shown on the Plan shall include:\na) Locality of the site, a north point and scale.\nb) Existing contours of the site including catchment area boundaries and indications of\ndirection of fall.\nc) Location of and basic description of existing vegetation.\nd) Diversion of uncontaminated up-slope run-off around the disturbed sites.\ne) Location of significant natural areas requiring special planning or management\nincluding waters, floodplains, seasonally wet areas, areas prone to ponding/water\nlogging, unstable slopes etc.\nf) Nature and extent of earthworks, including cut and fill roadworks.\ng) Location of all soil and material stockpiles.\nh) Location of site access, proposed roads and other impervious areas.\ni) Existing and proposed drainage patterns.\nj) Location and type of proposed erosion and sediment control measures.\nk) Site rehabilitation proposals, including final contours.\nl) Time of placement of sediment controls.\nm) Staging of works and how the plan is to be implemented for each stage or activity on\nsite.\nn) Maintenance schedule.\nReason: To minimise soil erosion and sediment movement during construction.\n49. Flood Assessment Statement\nA Flood Assessment Statement shall be undertaken on the properties by a suitably\nexperienced professional to address Mittagong DCP’s Flooding Prescriptive Controls.\nThe statement shall ensure compliance with the following:\na) Requirements of Council’s Development Control Plan of Mittagong.\nb) Requirements of Wingecarribee Local Environment Plan 2010, Clause 7.9.\nc) Requirements of the “Stormwater & Flood Management Strategy by J. Wyndham\nPrince Issue D dated 24/10/2024.”\nReason: To ensure the development complies with flood standards.\n50. Noise Control Measures\nPrior to the issue of a Construction Certificate the Applicant shall:\na) Incorporate the recommendations set out in Chapters 4.3 and 6.2.4 of The Maltings\nDevelopment, 2 Colo Street, Mittagong DA Acoustic Assessment for M3 & M4 prepared\nby Acoustic Logic (Ref: 20230457.7/0102A/R1/PF; Rev: 1: dated 1/02/2024) (‘Acoustic\nReport’) into construction drawings and specifications for the proposed development\nsubmitted to the Principle Certifying Authority (PC); and\nb) Incorporate the recommendations set out in Chapters 6.1 and 6.1.1 of the approved\nAcoustic Report into the selection and design of mechanical plant and equipment.\nReason: To prevent loss of amenity to the area.\n51. Food Premises Requirements\nPrior to the issue of a Construction Certificate, the construction drawings and specifications\nfor the food premises shall comply with all applicable food legislation/regulation and\nstandards, including:\n• Food Act 2003;\n• Food Regulation 2010;\n• Food Standards Code;\n• Australian Standard AS4674- 2004 Design, Construction and Fit out of Food\nPremises; and\n• Australian Standard AS1668.2- 2012 The use of ventilation and airconditioning in\nbuildings - Mechanical ventilation in buildings.\nThe construction and fit -out drawings and specifications shall clearly show all the required\ndetails including but not limited to the following:\n(a) Either a double- bowl sink or both a single- bowl sink and a commercial dishwasher\n(AS 4674, clause 4.1.1). This is in addition to any designated preparation sink and\ndesignated hand wash basin(s) mentioned below in the Items (b) and (c) respectively;\n(b) A designated preparation sink (if required) (AS 4674, clause 4.1.2);\n(c) Hand wash basins within all areas where unprotected food is handled. There shall be\nno more than 5 m walking distance from any area where open food is handled to the\nnearest hand wash basin (AS 4674, clause 4.4.1).\n(d) Adequate storage for the following:\n(i) food ingredients, including dry, cold and frozen ones (AS4674, clause 2.1.3);\nand\n(ii) personal effects (clauses 2.1.3 & 5.5.1).\n(e) Floor, wall and ceiling materials and finish (complying with AS4674, clause 3.1);\n(f) Coving to the intersections of walls to floors and floors to plinths in food preparation\nareas (AS4674, clause 3.1.5);\n(g) A facility for disposing of mop water and similar liquid waste, such as a cleaner’s sink,\nfloor waste, or other similar facility connected to drainage that is not intended for use\nto prepare food, wash any equipment or for hand washing (AS4674, clause 4.1.8).\n(h) Pipes, conduits and wiring in food preparation areas shall be installed in a complying\nmanner (AS4674, clause 3.2.9), i.e.:\n• either concealed in floors, plinths, walls and ceilings, or\n• fixed on brackets providing at least 25 mm clearance between the pipe or\nconduit and adjacent vertical surface, and 150 mm between the pipe or\nconduit and adjacent horizontal surface.\n(i) Design and construction of fixtures, fittings and equipment (AS4674, clause 4.2);\n(j) Kitchen fittings/equipment shall have appropriate supports (AS4674, clause 4.3.2),\nsuch as:\n• legs designed that there is a clear space between the floor and the underside\nof the fitting/equipment of not less than 150 mm; or\n• be fitted directly to plinths in such a manner that a complete seal is made\nbetween the floor and the base of the fittings/equipment; or\n• wheels or castors that are able to support the weight of the fully loaded\nequipment and enable it to be easily moved by one person.\n(k) Provisions for the collection and storage of garbage and recyclable materials\n(AS4674, part 2.4).\nReason: Compliance with legislation and standards.\n52. Grey-headed Flying Fox Management Plan\nA Grey-headed Flying-Fox Management Plan (GHFFMP) is to be prepared and must include\nat a minimum the following measures:\n• Opportunities to phase out the Salix trees in the instance that annual monitoring\nidentifies GHFF using re -planted established natives or retained natives instead. In\nthis instance, the Salix may be removed and replaced with suitable native tree\nplantings which GHFF are known to utilise for roosting. Similarly, if GHFF are not\nrecorded for a number of years, the Salix should be replaced with suitable native trees\nrepresentative of the locally occurring vegetation.\n• A restriction must be included that states “active dispersal is not to be used as a\nmanagement tool for this camp (whether a permanent or temporary gathering)”.\n• A no-go zone will be implemented during construction. Maps showing no go areas to\nbe placed in site offices, all staff briefed during toolbox talk or pre-work briefing on the\nlocation of the GHFF.\n• Measures for chance find procedures and education for site staff, including detail on\nAustralian Bat Lyssavirus.\n• Prior to works commencing, a preclearance survey specifically targeting the GHFF\nmust be completed. The survey will identify the extent of the camp, location, size and\nnumbers. A suitably experience ecologist will then advise on further mitigation\nmeasures required.\n• On the first day of construction, a suitably qualified ecologist must be present to\nmonitor any GHFF present. If bats in the camp become distressed and do not settle,\nworks must cease until the bats settle. If the GHFF camp continues to become\ndistressed, other mitigation measures such as noise attenuation may be required.\nThis measure should be conducted daily for as long as recommended by the suitably\nqualified ecologist.\n• If individual bats are seen flying consistently during the day, works must cease, and\nthe ecologist will be called to provide further advice.\n• Restriction to work hours to avoid flyout and return for the species (i.e. dusk and\ndawn).\n• Install noise barriers or daily/seasonal timing of construction and operational activities\nto reduce impacts of noise if GHFF individuals are agitated and do not settle during\nconstruction. Winter is considered best due to the deciduous nature of the trees the\nGHFF are utilizing.\nThe GHFFMP must be approved by Council prior to the issue of the Construction Certificate.\n53. Microbat Management Plan\nA Microbat Management Plan (MMP) is to be prepared. The MMP must include a suitable\ndegree of required survey to further inform management. Prior to the issue of the\nConstruction Certificate, the MMP is to be approved by Council and include at a minimum:\n• Pre-clearance survey over 4 nights per structure, by suitably qualified ecologists\nutilising ultrasonic recorders, infrared cameras, and diurnal and nocturnal searches\nof all suitable structures. Evening surveys must be conducted to capture flyouts,\nincluding thermal scanning and ultrasonic recording to ID any microbats that may be\npresent. Dusk exit surveys are to be conducted when temperatures are >14°C, in fine\nweather (i.e. no rain on either day) and preferably from September to April. The\nresults will inform further management, such as exclusion events and where to focus.\nA pre-exclusion survey is to take place that identifies likely or potential roost sites,\nwith these sites inspected up close. Visual aids with the ability to detect thermal\nsignatures are useful in these scenarios, with the hot spot of a bat potentially vi sible\neven if no direct line of sight is possible. These surveys are to be conducted by an\necologist with demonstrated experience in such work.\n• If microbats are recorded, additional habitat must be installed within the Study Area.\nAdditional habitat must be specific to the species recorded. Where suitable, this may\nbe incorporated into the refurbishment of the buildings. Council must provide approval\nof details on all proposed habitat as described in the MMP and should be consulted\nin the design process. Consideration must be given around the longevity of additional\nhabitat, thermal stability and likelihood of uptake. The use of plywood boxes is\ngenerally discouraged as a default for the provision of compensatory habitat for\nmicrobats roosting in artificial structures. Other materials, preferably consistent with\nroost sites to be impacted, should be considered. The use of plywood boxes may be\ndeemed suitable if sufficient justification is provided in the MMP, with the justification\nto outline other materials that were considered.\n• Should microbats be located, they must be excluded from the building by a suitably\nexperienced ecologist. If exclusion is not successful, translocation may be considered\nis consultation with Council and relevant State departments.\n• A chance find procedure and training module for construction staff must be included\nwithin the MMP.\n• Ongoing monitoring of supplementary artificial habitat must be included for a\nminimum of five years, conducted twice a year. The frequency of monitoring will be\nreconsidered by Council at the end of the 5 year period.\n54. Tree Retention Plan\nPreparation of a tree retention plan is required prior to the issue of the Construction\nCertificate. Of note, trees covered by the BV map in the vicinity of M4 must be clearly labelled\nfor protection.\n55. Damage Deposit for Council Infrastructure\nA damage deposit in accordance with Councils Bonds Policy shall be paid to Council prior to\nthe issue of the Construction Certificate.\nThis damage deposit shall be refunded upon completion of all works, on the issue of the Final\nOccupation Certificate. Any costs associated with works necessary to be carried out to rectify\nany damages caused by the development, shall be deducted from the damage deposit.\nNote: Full panel concrete footpath replacement in areas where connection to all\nservices are required. This includes driveways and road concrete panels. This\nwill stop differential settlement and maintain the integrity of council\ninfrastructure and asset.\nReason: Protection of Council infrastructure.\n56. Heritage Architect to be Commissioned\nA suitably qualified and experienced heritage consultant must be commissioned for the\nproject.\nThe nominated heritage consultant must:\n• provide input into the detailed design.\n• be consulted and provide input on the Interpretation Plan required by these conditions.\n• provide heritage information to be imparted to all tradespeople during site inductions,\n• oversee the works to minimise impacts to heritage values, and\n• be involved in the selection of appropriate tradespersons.\nProof of this engagement must be provided before the release of the construction certificate.\nReason: To protect heritage values across the site.\n57. Interpretation Plan\nA comprehensive interpretation strategy and plan for the site is to be prepared and submitted\nto Wingecarribee Council, in accordance with the Heritage NSW publication ‘Interpreting\nHeritage Places and Items Guidelines’ (2005), prior to the issue of any Construction\nCertificate.\nThe plan shall be developed to integrate:\n• interpretive options including tours, displays and visually appropriate signage (entry,\nwayfinding and interpretive signs),\n• events and activities,\n• conservation of significant elements including natural, landscape and built components, and\n• the inventory of existing significant items of movable heritage associated with The Maltings\n(opportunities for using these items to interpret the industrial use and history of the site in the\nredevelopment of the site is to be included in the plan).\nThe plan must respond to, and convey, significant Aboriginal and non- Aboriginal cultural\nvalues of the place as recognised by relevant Conservation Management Plans and listings\nof the site.\nThe plan shall identify the types, locations, materials, colours, dimensions, fixings and text of\ninterpretive devices that will be installed as part of this project.\nThe approved interpretation plan must be implemented prior to the issue of an Occupation\nCertificate.\nReason: Heritage conservation.\n58. Building works to comply with BCA - Heritage Buildings or Buildings Within\nConservation Area\nAny building works required to ensure compliance with the BCA or new building standards\nnot specified in the submitted/approved plan must not damage existing fabric and building\nfeatures.\nIf such upgrading works will potentially impact on existing fabric and features, details of the\nworks must be submitted and approved by Council’s Heritage Advisor prior to issue of a\nConstruction Certificate.\nReason: Heritage conservation.\n59. Structural engineering assessment\nPrior to the issue of any Construction Certificate, a Structural Engineering assessment report\naccompanied by working drawings and specifications, must be submitted to the satisfaction\nof Council and must demonstrate the measures that will be implemented, together with the\nmethodology for undertaking excavation works both within the vicinity\nand adjacent to the heritage item.\nThe Structural Engineering assessment report, working drawings and specifications, must:\na) Be prepared by a suitably qualified Structural Engineer with demonstrated experience in\ndealing with items of heritage significance and heritage fabric; and\nb) Demonstrate that the heritage item can be retained in a safe manner that will ensure the\nretention and protection of significant fabric and, minimise to the greatest extent possible any\nmaterial affectation (such as deconstruction, new penetrations or the like) to otherwise\nunderpin, support or ensure the retention and protection of fabric; and\nc) Demonstrate and certify that the excavation works will not cause the collapse in part or in\nfull of any section of the building, its footings or substrate, as shown on the approved plans\nto be retained.\nReason: Heritage conservation.\n60. Schedule of Conservation Works\nA detailed schedule of conservation works for the significant buildings and landscape\ncomponents of the site must be prepared by a suitably qualified heritage consultant. The\nSchedule is to be in accordance with the Burra Charter guidelines and guided by the\nConservation Management Plan.\nThe schedule of conservation works is to be submitted to Council for approval prior to the\nissue of the Construction Certificate.\nThe works are to be implemented prior to the issue of an Occupation Certificate, to ensure\nthat significant features and fabric are restored and conserved.\nReason: To protect heritage values across the site.\nCONDITIONS TO BE SATISFIED DURING THE CONSTRUCTION PHASE\n61. Approved Plans to be available on site\nEndorsed Council approved plans, specifications, documentation and the consent shall be\nmade available on site at all times during construction.\nReason: To ensure compliance with approved plans.\n62. Asbestos Removal - Demolition of Buildings\na) Demolition is to be carried out in accordance with the applicable provisions of Australian\nStandard AS2601-2001 - The demolition of structures.\nNote: Developers are reminded that SafeWork requires that all plant and equipment used\nin demolition work must comply with the relevant Australian Standards and\nmanufacturer specifications.\nb) The developer is to notify owners and occupiers of premises on either side, opposite and\nat the rear of the development site five (5) working days prior to demolition. Such\nnotification shall state the date demolition will commence and is to be placed in t he\nletterbox of every premises (including every residential flat or unit, if any) either side,\nimmediately at the rear of, and directly opposite the demolition site. Demolition must not\ncommence prior to the date stated in the notification.\nc) Five (5) working days (i.e., Monday to Friday with the exclusion of Public Holidays) notice\nin writing is to be given to the Principal Certifier (PC) for inspection of the site prior to the\ncommencement of works. Such written notice is to include the date when demolition will\ncommence and details of the name, address, business hours contact telephone number\nand licence number of the demolisher. Works are not to commence prior to the PC’s\ninspection and works must not commence prior to the commencement date nominated\nin the written notice.\nd) On the first day of demolition, work is not to commence until the PC has inspected the\nsite. Should the building to be demolished be deemed likely to contain asbestos,\napproval to commence demolition will not be granted until the PC is satisfied that all\nmeasures are in place so as to comply with SafeWork’s document ‘Your Guide to\nWorking with Asbestos’.\ne) On demolition sites where buildings to be demolished are likely to contain asbestos, a\nstandard commercially manufactured sign containing the words “DANGER ASBESTOS\nREMOVAL IN PROGRESS” measuring not less than 400mm x 300mm is to be erected\nin a prominent visible position on the site to the satisfaction of the PC. The sign is to be\nerected prior to demolition work commencing and is to remain in place until such time as\nall asbestos has been removed from the site to an approved waste facility.\nf) Demolition works involving the removal and disposal of asbestos cement shall only be\nundertaken by contractors who hold a current SafeWork “Demolition Licence” and a\ncurrent SafeWork “Class 2 (Restricted) Asbestos Licence”.\ng) Demolition is to be completed within five (5) days of commencement at which time the\napplicant shall notify the PC.\nh) Demolition works are restricted to Monday to Friday between the hours of 7.00am to\n6.00pm. No demolition works are to be undertaken on Saturdays, Sundays or Public\nHolidays.\ni) Protective fencing is to be installed to prevent public access to the site.\nj) All asbestos laden waste, including asbestos cement flat and corrugated sheets must be\ndisposed of at a facility licensed by the NSW Environmental Protection Authority (EPA)\nto accept such waste provided to the PC.\nNote: The person responsible for disposing of the above asbestos waste is to telephone the\nEPA on 131 555 or Council on (02) 4868 0888 to determine the location of a waste\nfacility licensed to receive asbestos. Within 14 days of the completion of demolition\nworks, the applicant must lodge with the PC, all original weighbridge receipts issued\nby the receiving licensed waste facility as evidence of proper disposal.\nk) After completion, the applicant shall notify the PC within seven (7) days to assess the\nsite and ensure compliance with Australian Standard AS2601 2001 - The Demolition of\nStructures.\nl) Within 14 days of the completion of demolition and removal of all demolition waste or, if\napplicable, by such later date as may be specified by Council’s Environmental Health\nOfficer, the applicant shall provide the following documents to the satisfaction of both the\nPC and Council’s Environmental Health Officer:\n(i) an asbestos clearance certificate issued in accordance with the requirements of\nWork Health and Safety Regulation 2017;\n(ii) a written statement signed by a duly qualified person verifying that the demolition\nwork and removal, recycling and disposal of all waste materials was undertaken in\naccordance with the Waste Management Plan submitted with the development\napplication;\n(iii) all Transport Certificates (TCs) for the transport of all trackable demolition waste\nfrom the site to the receiving facility; and\n(iv) the actual weighbridge receipts for the recycling and disposal of all materials.\nm) In the event that the applicant fails to provide the documents mentioned in the item ‘l’ to\nthe satisfaction of Council’s Environmental Health Officer, the applicant will be requested\nto provide further reports and/or documentation in order to demonstrate that the site was\ncleared of asbestos and all asbestos containing materials have been properly disposed\nof to a facility licensed by the NSW Environmental Protection Authority (EPA) to accept\nsuch waste. The applicant will be required to submit such further reports and/or\ndocumentation within the timeframe specified by Council’s Environmental Health Officer.\nReason: To ensure that asbestos is disposed of to a licensed waste facility and is\nremoved in accordance with safe work practices.\n63. Imported 'Waste-derived' Fill Material\nThe only waste derived fill material that may be received at the development site is:\n Virgin excavated natural material (VENM) within the meaning of the Protection of the\nEnvironment Operations Act 1997 (POEO); or\n Any other waste-derived material the subject of a resource recovery exemption under\nclauses 91 & 92 of the Protection of the Environment Operations (Waste) Regulation\n2014 that is permitted to be used as fill material\nNote: Any waste-derived fill material the subject of a resource recovery exemption\nreceived at the development site must be accompanied by documentation as\nto the material's compliance with the exemption conditions and must be\nprovided to the Principal Certifier (PC).\nThe application of waste -derived material to land is an activity that may require a licence\nunder the Protection of the Environment Operations Act 1997 . However, a licence is not\nrequired if the only material applied to land is virgin excavated natural material or waste-\nderived material that is the subject of a resource recovery exemption under clauses 91 & 92\nof the Protection of the Environment Operations (Waste) Regulation 2014.\nResource recovery exemptions are available on the NSW EPA website at\nhttp://www.epa.nsw.gov.au/waste/.\nReason: To ensure that imported fill is of an acceptable standard for environmental\nprotection purposes.\n64. Engineering Inspections by Council\n24 hours prior to the covering of the following works, Council shall be notified by the licensed\nbuilder, owner builder or licensed plumber/drainer that the following works are ready for\ninspection:\na) Works in relation to road reserves, footpath, kerb and gutter, road shoulder and\ndrainage within public lands or road reserves.\nb) Piers to distribute loading from structure away from sewer main.\nc) Final inspection of footpath, driveway, stormwater and utility construction works within\nthe road reserve.\nNote: The subject building is not to be occupied until an Interim or Final Occupation\nCertificate is issued.\nNote: An accredited certifier may not be substituted for Council in respect of these\ninspections, as Council remains the sole responsible authority for these\nmatters.\nReason: Statutory requirement.\n65. Ground Levels\nNatural ground levels shall not be altered or adjusted other than shown on the approved\nplans or where varied by the conditions of consent without the prior consent of Council.\nFinished ground levels shall be graded away from the buildings and adjoining properties must\nachieve natural drainage. The concentrated flows are to be dispersed down slope or collected\nand discharged to an approved storm water drainage system.\nReason: To ensure that natural drainage of the property and adjoining properties is not\naffected.\n66. Earthworks, retaining walls and structural support\nAny earthworks (including any structural support or other related structure for the purposes\nof the development):\n(a) must not cause a danger to life or property or damage to any adjoining building or\nstructure on the lot or to any building or structure on any adjoining lot, and\n(b) must not redirect the flow of any surface or ground water or cause sediment to be\ntransported onto an adjoining property, and\n(c) that is fill brought to the site -must contain only virgin excavated natural material\n(VENM) as defined in Part 3 of Schedule 1 to the Protection of the Environment\nOperations Act 1997 or any other waste -derived material the subject of a resource\nrecovery exemption under clauses 91 & 92 of the Protection of the Environment\nOperations (Waste) Regulation 2014 that is permitted to be used as fill material, and\n(d) that is excavated soil to be removed from the site-must be disposed of in accordance\nwith any requirements under the Protection of the Environment Operations (Waste)\nRegulation 2005.\nAny excavation must be carried out in accordance with Excavation Work: Code of Practice\n(ISBN 978-0-642-785442), published in October 2013 by Safe Work Australia.\nReason: Structural safety.\n67. Damage to Adjoining Properties\nAll precautions shall be taken to prevent any damage likely to be sustained to adjoining\nproperties. Where damage occurs to adjoining property all necessary repair or suitable\nagreement for necessary repairs shall be undertaken by the applicant in consultation with,\nand with the consent of, the affected property owner.\nReason: Structural safety.\n68. Prevention of Nuisance\nAll possible and practical steps shall be taken to prevent nuisance to the inhabitants of the\nsurrounding neighbourhood from windblown dust, debris and noise during the demolition,\nexcavation and building works.\nReason: Health and amenity.\n69. Building Operations\nBuilding operations such as brick cutting, washing tools or brushes and mixing mortar are not\npermitted on public roadways or footways or in any other locations which could lead to the\ndischarge of materials into the storm water drainage system.\nReason: To ensure that building materials are not washed into storm water drains.\n70. Maintenance of the site\nAll materials and equipment shall be stored wholly within the work site.\nWaste materials (including excavation, demolition and construction waste materials) shall be\nmanaged on the site and then disposed of at a waste management facility.\nAny run-off and erosion control measures required shall be maintained within their operating\ncapacity until the completion of the works to prevent debris escaping from the site into\ndrainage systems, waterways, adjoining properties and roads.\nDuring construction:\n(a) all vehicles entering or leaving the site shall have their loads covered, and\n(b) all vehicles, before leaving the site, shall be cleaned of dirt, sand and other materials,\nto avoid tracking these materials onto public roads.\nAt the completion of the works, the work site shall be left clear of waste and debris.\nReason: Environmental amenity.\n71. Excavations and Backfilling\nAll excavations and backfilling associated with the erection or demolition of a building shall\nbe executed safely and in accordance with appropriate professional standards properly\nguarded and protected to prevent them from being dangerous to life or property.\nReason: To ensure the safety of life and property.\n72. Approved hours of Construction/Demolition\nConstruction/demolition activities shall be limited to the following hours:\nDAY HOURS\nMonday to Saturday 7:00am to 5:00pm\nSunday Nil\nPublic Holidays Nil\nReason: To ensure that the amenity of the surrounding area is not compromised as a\nresult of the construction of the proposal.\nNote: Any variation to these hours shall require Council consent via the lodgement\nof an application under section 4.55 of the Environmental Planning and\nAssessment Act 1979.\n73. Temporary Onsite Toilet\nToilet facilities shall be available or provided at the work site prior to the commencement of\nworks and must be maintained until the works are completed at a ratio of one toilet plus one\nadditional toilet for every 20 persons employed at the site.\nEach toilet shall:\n(a) be a standard flushing toilet connected to a public sewer, or\n(b) have an on-site effluent disposal system approved under the Local Government Act\n1993, or\n(c) be a temporary chemical closet approved under the Local Government Act 1993.\nReason: To ensure that there are appropriate facilities on-site for construction workers.\n74. Waste Management\nThe provision of a metal waste skip with self -closing lid or secure covering on- site for the\nduration of the construction to ensure that all wastes are contained on the site. The receptacle\nshall be emptied periodically to reduce the potential for rubbish to leave the site.\nSorting of waste materials shall occur on site in accordance with the approved Waste\nManagement Plan.\nReason: To ensure that all wastes generated from the construction of the development\nare contained on the site.\n75. Stormwater - Construction\nThe applicant shall provide adequate storm water drainage infrastructure (pits/pipes/open\nchannels/detention storage) for the conveyance of storm water passing through the site from\nupstream, and sourced from the development to a discharge outlet to be approved by\nCouncil. The point of discharge shall be clearly depicted and the legal right to discharge at\nthat point to be justified. Status of the point of discharge is to be made clear (i.e. provision of\ndrainage easements).\nReason: To assist in the prevention of erosion of the site from storm water.\n76. Stormwater - Discharge\nAll stormwater runoff from the development shall be collected within the property and\ndischarged to an approved stormwater management system.\nReason: To ensure that stormwater is appropriately disposed of.\n77. Erosion and Sediment Control Plan Compliance\nAll site works shall be carried out in accordance with the approved Erosion and Sediment\nControl Plan. Implementation of the Erosion and Sediment Control Plan shall be supervised\nby personnel with appropriate qualification and experience in erosion and sediment control.\nNote: In the event of non-compliance with the approved plan, Council Officers have\nthe ability to issue Penalty Notices, being an on the spot fine and/ or orders.\nReason: To ensure that stormwater is appropriately disposed of.\n78. Construction Management Plan\nAll development activities and traffic movements shall be carried out in accordance with the\napproved Construction Management Plan.\nAll controls in the Plan shall be maintained at all times. A copy of the Plan must be kept on\nsite at all times and made available to the Accredited Certifier and Council on request.\nReason: Compliance with condition of consent.\n79. Felling Supervision\nFelling supervision of all trees, including exotic pines which are known to provide ample\nhabitat to native arboreal fauna, must be undertaken by suitably qualified ecologists.\n80. Clearing of Existing Vegetation\nDuring construction activities, when clearing areas of existing vegetation, earthworks and\ntree removal should be undertaken with the fauna ecologist or wildlife carer to supervise\nworks. All native timber should be retained, with mulch stockpiled for use within the VMP\narea, all viable seed and genetic material to be collected and all timber cut into logs to be\nutilised as habitat for native fauna.\n81. Habitat Structures\nEucalypts earmarked for removal within the development area should be used as habitat\nstructures within the VMP area. This includes the use of fallen woody debris as habitat or for\nmulch. Mulch should be free of weed propagules. It is assumed that no native hollow-bearing\ntrees will be removed under the development footprint.\n82. Koala Fencing\nWhere fencing is proposed along the Natai riparian corridor, then koala friendly fencing must\nbe utilised which would allow for the rare, but potential movement of koalas along the corridor.\nThis means any fencing must allow koalas to move either under, through or over fencing, or\nhave a suitable alternative route.\n83. Compliance and Implementation of Conservation Management Plan\nThe Applicant is to ensure the ongoing compliance and implementation of the Conversation\nManagement Plan approved by Development Consent 20/1400 (as modified by 24/1140).\nReason: Heritage conservation.\n84. Archaeology\nAs required by the National Parks and Wildlife Service Act 1974 and the Heritage Act 1977,\nin the event that Aboriginal cultural heritage or historical cultural fabric or deposits are\nencountered/discovered where they are not expected, works must cease immediately and\nCouncil and Heritage NSW must be notified of the discovery.\nIn the event that archaeological resources are encountered, further archaeological work may\nbe required before works can re-commence, including any the statutory requirements under\nthe Heritage Act 1977.\nNote: The National Parks and Wildlife Service Act 1974 and the Heritage Act 1977 impose\nsubstantial penalty infringements and / or imprisonment for the unauthorised\ndestruction of archaeological resources, regardless of whether or not such\narchaeological resources are known to exist on the site.\nReason: Statutory requirements for the protection of archaeology.\n85. Reduction of rising damp and salt attack in buildings constructed prior to 1930\nTo avoid potential damage caused by rising damp and migrating salts, no concrete slab or\napron is to be laid directly on the ground either within the footprint of a masonry (brick or\nstone) building, or directly adjacent to the exterior walls of any masonry building, unless\ndesigned and constructed in a manner that ensures an isolating moisture barrier, the\nprotection of significant fabric, and supported by the Structural Engineer and Heritage\nConsultant.\nReason: Heritage conservation.\n86. Temporary storage of materials, equipment and waste during works\nAll construction materials, equipment and demolition / construction waste shall be stored\nwholly within the allotment boundaries and shall be stored, contained or stockpiled in such\nlocations that do not cause any impacts to existing built structures including ancillary\nstructures, walls or fences, or established gardens.\nReason: Protection of significant features of the site.\n87. Conservation works to be overseen by Heritage Consultant\nA Heritage Consultant experienced in conserving buildings of significance is to be\ncommissioned to work with the consultant team throughout the design development, contract\ndocumentation and construction stages of the project.\nThe Heritage Consultant is to be involved in the resolution of all matters where existing\nsignificant fabric and spaces are to be subject to preservation, restoration, reconstruction,\nadaptive reuse, recording and demolition. The Heritage Consultant is to be provided with full\naccess to the site and authorised by the applicant to respond directly to Council where\ninformation or clarification is required regarding the resolution of heritage issues throughout\nthe project.\nEvidence and details of the above commission on the above terms are to be provided to\nCouncil’s Heritage Advisor prior to commencement of work on site. The Heritage Consultant\nmust sign off the completed project and submit a final report to Council’s Heritage Advisor\nspecifying how the heritage conditions are satisfied prior to the issue of an Occupation\nCertificate or the commencement of the use, whichever is earlier.\nReason: Heritage conservation.\n88. Undertaking of conservation works to the heritage item\nAll conservation works to the heritage item, including the approved demolition of fabric and\nnew additions, shall be undertaken:\na) By suitably qualified trades / specialists, with demonstrated practical experience in dealing\nwith heritage fabric and good practice heritage methodology.\nb) In accordance with the Articles of the Australia ICOMOS Burra Charter (2013), the\napproved Schedule of Conservation Works and the ‘Conservation Management Plan’\n(prepared by Paul Davies Pty Ltd).\nc) In accordance with the conditions of this consent.\nd) In a manner that minimises demolition, alterations and new penetrations/fixings to the\nsignificant fabric of the existing heritage item.\ne) In a manner that all fabric and features to be retained are properly protected during the\nprocess of demolition, construction and conservation works.\nReason: To ensure the protection and retention of significant fabric.\n89. General Heritage\n(a) The proposed works are to be carried out in a manner that minimises demolition,\nalterations and new penetrations/fixings to the significant fabric of the existing heritage item.\n(b) The fabric and features to be retained by the proposal must be properly protected during\nthe process of demolition and construction.\n(c) All conservation and adaptation works are to be in accordance with the Articles of the\nAustralia ICOMOS Burra Charter (2013).\n(d) New services are to be surface mounted rather than chased- in to existing walls to\nminimise impact on significant heritage fabric.\n(e) Appropriately qualified tradespersons (as appropriate) are to be commissioned who are\nskilled in traditional building and engineering trades to carry out the proposed scope of works.\nReason: Heritage conservation.\n90. No demolition of extra fabric\nAlterations to, and demolition of, the existing building shall be limited to that documented on\nthe approved plans (by way of notation) or conditioned in this consent.\nNo approval is given or implied for removal and/or rebuilding of any portion of the existing\nbuilding which is shown to be retained.\nShould any portion of the existing building which is indicated on the approved plans to be\nretained, be damaged for whatever reason, all the works in the area of this damaged portion\nare to cease and written notification given to Council.\nNo work is to resume until the written approval of Council is obtained. Failure to comply with\nthe provisions of this condition may result in the Council instituting legal proceedings.\nReason: Heritage conservation.\n91. Uncovering of concealed architectural features or detailing\nShould any concealed architectural features or detailing, not previously noted in the DA\ndocumentation, be discovered during demolition or building works, all works are to\nimmediately cease and the architectural features or detailing to be photographically recorded\nand Council’s Heritage Advisor is to be contacted for advice.\nReason: Heritage conservation.\nCONDITIONS TO BE SATISFIED PRIOR TO THE ISSUE OF AN INTERIM OR FINAL\nOCCUPATION CERTIFICATE\n92. Occupation Certificate\nIn accordance with Section 6.9 of the Environmental Planning and Assessment Act 1979, an\napplication for an Occupation Certificate, shall be made on completion of the works and the\nrelevant application fee paid. All works specified in the development consent and approved\nConstruction Certificate plans shall be completed and all development consent conditions\ncomplied with prior to the issue of the Occupation Certificate.\nThe Principal Certifier (PC) is required to be satisfied, amongst other things, that:\n• All required inspections (including each applicable mandatory critical stage\ninspection) have been carried out; and\n• Any preconditions to the issue of the certificate required by a development consent\nhave been met.\nReason: To comply with the provisions of the Environmental Planning and Assessment\nAct 1979\nNote: A person must not commence occupation or use (or change of use where an\nexisting building) of the whole or any part of a new building (within the meaning\nof Section 6.10 of the Environmental Planning and Assessment Act 1979\nunless an Occupation Certificate has been issued in relation to the building or\npart.\n93. Occupation Certificate\nThe Development shall not be occupied or used until an Occupation Certificate is issued by\nthe Principal Certifier.\nReason: To ensure compliance with the Environmental Planning and Assessment\n(Development Certification and Fire Safety) Regulation 2021.\n94. Building Upgrade Measures\nAll building upgrade measures required to be installed pursuant to Section 64 of the\nEnvironmental Planning and Assessment Regulation 2021, shall be completed prior to use\nof the premises and the issue of an Occupation Certificate.\nReason: To ensure that the building is upgraded to comply with the Building Code of\nAustralia\n95. Section 138 Roads Act Final\nThe applicant is to ensure that the works associated with the Section 138 approval for this\ndevelopment be completed and inspected by Council prior to the issue of any Occupation\nCertificate.\nReason: To ensure that the development is completed as per this consent and the\napproved plans.\n96. Section 68 Local Government Act Final\nThe applicant is to ensure that the works associated with the Section 68 approval for this\ndevelopment be completed and inspected by Council prior to the issue of any Occupation\nCertificate.\nReason: To ensure that the development is completed as per this consent and the\napproved plans.\n97. Construction of Sewer Sidelines\nSidelines and junctions shall be installed for sewer connections to the development by\nCouncil at the Developer’s cost prior to the issue of any Occupation Certificate.\nCouncil’s application form shall be completed by the applicant and the appropriate fee paid.\nIf the sideline is to be extended from a sewer main in adjoining property, written permission\nof the affected landowner allowing work to be undertaken, shall be submitted with the\napplication form.\nReason: To ensure that the development is serviced.\n98. Construction of Water Service\nA single, adequately sized water service shall be installed to the development by Council at\nthe applicant’s cost prior to the issue of the Occupation Certificate. Council’s application form\nshall be completed by the Developer and the appropriate fee paid.\nAdvice: A water meter should be installed prior to construction commencing.\nReason: To ensure that the development is serviced.\n99. Redundant/Disused Sewer Services\nThe existing redundant/disused sewer junction that serves the lot is to be disconnected and\ncapped at the Applicant's expense prior to the issue of the Occupation Certificate.\nThe applicant shall provide to Council written confirmation of compliance.\nReason: To ensure that existing redundant sewer services are disconnected and\ndisused within the development.\n100. Council Property\nThe applicant shall rectify any damage to Council property (including footpaths, road\nfurniture, landscaping/trees, drainage, water, sewer, kerb and gutter, road pavement and the\nlike) as a result of the development, prior to the issue of any Occupation Certificate at no cost\nto Council.\nReason: To ensure that Councils assets are protected.\n101. Final Fire Safety Certificate\nPrior to the issue of any Occupation Certificate, a Final Fire Safety Certificate shall be\nsubmitted to the nominated Principal Certifier, to certify that all of the essential fire safety\nmeasures / services as listed in the approved Fire Safety Schedule have been satisfactorily\ninstalled.\nThe Final Fire Safety Certificate shall be accompanied by installation certification for each\nessential fire safety measure / service from the licensed installer.\nReason: To ensure compliance with the Environmental Planning and Assessment\n(Development Certification and Fire Safety) Regulation 2021.\n102. Civil Engineering works and services\nAll civil engineering works and services are to be constructed in accordance with the\nWingecarribee Shire Council Engineering Plans and Specifications, relevant Standards and\napproved engineering plans prior to the issue of the Occupation Certificate.\nReason: To ensure that the works and services are constructed in accordance with the\napproved plans.\n103. Certification of Internal Civil Works\nOn completion of the works and prior to the issue of the Occupation Certificate, certification\nfrom a professional engineer who has appropriate experience and competence in the relevant\nregistered area of practice, shall be submitted to Council detailing t hat all the internal civil\nworks (i.e. internal driveways, paths and stormwater drainage system, including any onsite\ndetention) are in accordance with the approved plans and specifications.\nReason: Asset management.\n104. Flooding - Finished Surface Level Work as Executed\nPrior to the issue of the Occupation Certificate , the works as executed plans shall be\nsubmitted to the Principal Certifier and shall state the 1% AEP flood level and the minimum\nfinished floor level. The finished floor level is to be a minimum of 500mm above the 1% AEP\nflood level in accordance with the “Stormwater & Flood Management Strategy by J.\nWyndham Prince issue D dated 24/10/2024.”\nReason: To ensure appropriate flood protection to property.\n105. Vehicle Access\nAccess to the site shall be provided by means of a vehicle crossing as per Standard Drawing\nSD107, SD108 and SD123 approved by Council prior to the issue of the Occupation\nCertificate. A copy of the Standard Drawing can be obtained from Council’s offices.\nReason: To ensure that the driveway is constructed to Councils standard specification.\n106. Defects and Liability Bond for Public Assets - Civil Works\nPrior to the issue of any Occupation Certificate the developer shall lodge a cash bond to\ncover the defects liability period of 24 months for any public infrastructure constructed by\nthem which will handed over to council. The liability period will commenc e from the date of\nissue of the\nOccupation Certificate.\nThe security bond will be in an amount equal to 10% of the value of the total building works\nwith a minimum value of $10,000 based on the building costs supported by written evidence\nin accordance with Council’s Bond Policy. The bond shall be assessed by Council for release\nafter the 24 month period on formal request from the developer.\nReason: To ensure appropriate warranty periods apply for defect liability.\n107. Engineering Certification - Flood Compatible Development\nPrior to issue of the Occupation Certificate, an Engineering Certification to the Principal\nCertifier shall be provided for any proposed development to occur within the area identified\nas inundated by the 1:100 year ARI event to ensure compliance with the following:\na) Requirements of Council’s Development Control Plan of Mittagong.\nb) Requirements of Wingecarribee Local Environment Plan 2010, Clause 5.21.\nc) Requirements of the “Stormwater & Flood Management Strategy by J. Wyndham Prince\nIssue D dated 24/10/2024.”\nReason: To ensure the development complies with flood standards.\n108. Noise Control Measures\nPrior to the issue of an Occupation Certificate the Applicant shall:\na) Incorporate the recommendations set out in Chapters 4.3 and 6.2.4 of the approved\nAcoustic Report into the design, construction and fit-out of the proposed development;\nb) Incorporate the recommendations set out in Chapters 6.1 and 6.1.1 of the approved\nAcoustic Report into the selection, design, installation and fit-out of mechanical plant and\nequipment; and\nc) Incorporate the controls recommended in Chapter 6.2.4 of the approved Acoustic Report\ninto an Operational Plan of Management for the development.\nReason: To prevent loss of amenity to the area.\n109. Food Premises Requirements\nPrior to the issue of an Occupation Certificate, the food premises shall be constructed, fitted-\nout and set up in accordance with all applicable food legislation/regulation and standards,\nincluding:\n• Food Act 2003;\n• Food Regulation 2010;\n• Food Standards Code;\n• Australian Standard AS4674-2004 Design, Construction and Fit out of Food\nPremises; and\n• Australian Standard AS1668.2-2012 The use of ventilation and airconditioning in\nbuildings - Mechanical ventilation in buildings.\nReason: Compliance with legislation and standards.\n110. Landscape Certification\nCertification is to be provided to the Principal Certifying Authority (PCA) from the designer of\nthe approved landscape plan that all tree planting/landscape works have been carried out in\naccordance with the Council endorsed landscape plan. If Council is the PCA, the certification\nis to be submitted to Council prior to or at the final landscape inspection. If Council is not the\nPCA, a copy of the certification is to be provided to Council with the lodgement of the\nOccupation Certificate.\nReason: To ensure that the landscaping is completed prior to occupation.\n111. Conservation works to be undertaken and completed\nPrior to the issue of any Occupation Certificate, all conservation works detailed in the\napproved Schedule of Conservation Works and nominated in the consent documentation,\nshall be fully completed.\nWritten evidence shall be prepared by the Heritage Consultant engaged and responsible for\noverseeing the conservation works, attesting that all conservation works have been\nsatisfactorily completed in accordance with the Articles of the Australia ICOMOS Burra\nCharter (2013) and the Conservation Works Schedule. The Heritage Consultant’s attestation\nstatement shall be submitted to the satisfaction of Council’s Heritage Advisor.\nReason: Heritage conservation.\n112. Evidence of Compliance with Bushfire Measures\nPrior to the issue of any Occupation Certificate, certification must be provided by a BPAD\nLevel 3 accredited consultant that the bushfire measures required by the approval have been\ninstalled.\nReason: To ensure ongoing protection form bushfire.\n112A. Operational Plan of Management\nPrior to the issue of an Occupation Certificate, the applicant shall submit an amended\nOperational Plan of Management to Council’s Director of Communities and Place or their\ndelegate for approval which addresses all operational and management procedures for the\ndevelopment. The matters include but are not limited to:\na) the acoustic mitigation recommendations set out in Chapter 6.2.4 of the approved\nAcoustic Report listed in Condition 2 of this consent;\nb) provisions to ensure that that noise emissions generated by the use to satisfy criteria\nset out in the EPA’s Industrial Noise Policy 2000;\nc) management of deliveries, all loading and unloading operations associated with\nservicing the site must be carried out within the confines of the site, at all times and\nmust not obstruct other properties / units or the public way;\nd) management measures to control vehicle activity;\ne) the emergency management of the movement of people within and surrounding the\nsite;\nf) waste collection and maintenance of the site;\ng) security management - lighting, CCTV etc;\nReason: To ensure that the use can operate safely and without disturbance to the\nsurrounding locality.\nCONDITIONS TO BE SATISFIED DURING THE OPERATION AND USE OF THE DEVELOPMENT\n113. Annual Fire Safety Statement\nAll essential fire safety measures / services are to be inspected and certified in accordance\nwith the Environmental Planning and Assessment Act 1979, every 12 months from the date\nof the Occupation Certificate. Council shall be provided with a copy of the Annual Fire Safety\nStatement, Fire Safety Schedule and relevant inspection reports in accordance with the\nEnvironmental Planning and Assessment Act 1979.\nReason: To ensure compliance with the Environmental Planning and Assessment\n(Development Certification and Fire Safety) Regulation 2021\n114. Noise Control Measures\nDuring the operation and use of the development the Applicant shall:\na) Incorporate the recommendations set out in Chapters 4.3 and 6.2.4 of the approved\nAcoustic Report into the design, construction and fit -out of the proposed development.\nThis includes but is not limited to keeping all recommended acoustic fences and barriers\nin good repair;\nb) Incorporate the recommendations set out in Chapters 6.1 and 6.1.1 of the approved\nAcoustic Report into the selection, design, installation and fit-out of mechanical plant and\nequipment; and\nc) Keep the controls recommended in Chapter 6.2.4 of the approved Acoustic Report\nincorporated in the approved Operational Plan of Management for the development and\nexercise such controls.\nReason: To prevent loss of amenity to the area.\n115. Operational Noise Levels\nThe operational noise levels generated by the development shall be controlled such that they\ndo not exceed the applicable levels set in Tables 5.3 and 5.4 of the approved Acoustic Report\nwhen measured at the nearest affected receiver.\nIn the event that substantiated complaints are received, the Applicant will be required to\nundertake acoustic compliance testing and implement any requirements as are necessary to\nremedy such exceedance within a period determined by Council.\nReason: To prevent loss of amenity to the area.\n116. No painting or rendering of masonry or stone\nNo painting or rendering shall be permitted to masonry or stone surfaces which have not\npreviously been painted or rendered.\nReason: To protect the existing character of the heritage item, streetscape and\nHeritage Conservation Area.\n117. Operational Plan of Management\nThe development must be conducted in accordance with t he Operational Plan of\nManagement as approved by Council under this Development Consent.\nThe Plan of Management must be:\ni) kept current and onsite at all times;\nii) reviewed and updated if there are any operational changes, and a copy supplied to\nCouncil.\nNote: Changes to the Plan of Management must remain consistent with the\napproved conditions of this consent.\nThe contact details of the nominated contact person responsible in responding\nto any issues or complaints raised by the community or Council are to be\nalways displayed in a publicly visible location at the premises.\nA copy of the Plan of Management is to be available upon request and held\non site.\nReason: To prevent loss of amenity to the area and ensure ongoing compliance.\n118. Food Premises\nDuring operation of the development the design, construction, fit -out and operation of the\nfood premises shall comply with all applicable food legislation/regulation and standards,\nincluding:\n• Food Act 2003;\n• Food Regulation 2010;\n• Food Standards Code;\n• Australian Standard AS4674- 2004 Design, Construction and Fit out of Food\nPremises; and\n• Australian Standard AS1668.2- 2012 The use of ventilation and airconditioning in\nbuildings - Mechanical ventilation in buildings.\nIn the event that the design, construction and/or fit-out of food handling areas is inadequate\nfor the food handling activities carried out on the premises, the Applicant will be required to\nundertake such works as is necessary to remedy any non- compliance w ith the above-\nmentioned legislation and Standards within a period determined by Council, for which\nseparate prior development consent may be required.\nReason: Compliance with legislation and standards.\nEND OF CONDITIONS","stage":"general","stage_basis":"heading","page":16}]});
